// Pure public-list markup shared by the first HTML response and the browser.
export function listCategorySelect(boards,params,{t,esc,categoryName}){return boards?.length?`<select aria-label="${t("게시글 분류")}" id="board-filter"><option value="">${t("전체")}</option>${boards.map(board=>`<option value="${board.id}" ${String(board.id)===params.get('board')?'selected':''}>${esc(categoryName(board.name))}</option>`).join('')}</select>`:'';}

export function listMarkup(data,{params=new URLSearchParams(),boards,status,interactive=true,t,esc,dateText,numberText,categoryName}){
  const ctx={boards,status};
  const query=new URLSearchParams();for(const key of ['page','q','board'])if(params.get(key))query.set(key,params.get(key));
  const canWrite=!!ctx.status&&!ctx.status.communityPaused&&ctx.status.rich.enabled;
  const write=canWrite?`<a class="button primary" href="#write">${t("＋ 글쓰기")}</a>`:'';
  const pageLink=page=>{const next=new URLSearchParams(query);next.set('page',String(page));return '#list?'+next;};
  const first=Math.max(1,Math.min(data.page-2,data.pages-4)),pages=Array.from({length:Math.min(5,data.pages)},(_,i)=>first+i);
  // Display rank belongs to this filtered list; permanent IDs remain in links.
  const firstNumber=(data.regularTotal??data.total)-(data.page-1)*(data.limit||20);
  let ordinaryIndex=0;
  const categorySelect=boards=>listCategorySelect(boards,params,{t,esc,categoryName});
  return `<div class="page-heading community-heading" data-list-root><div class="community-heading__copy"><div class="community-heading__title"><h1>${t("커뮤니티")}</h1><div class="actions"><span data-list-write>${write}</span></div></div><p>${t("처음 오셨나요? 편하게 이야기 나눠요.")}</p></div>
    <picture class="community-heading__art" aria-hidden="true"><source media="(min-width:681px)" srcset="/community/art/community-panorama-960-cdd8e3d9fe11.webp 960w, /community/art/community-panorama-1440-2ce54df2c6ce.webp 1440w, /community/art/community-panorama-1920-ee56344e5239.webp 1920w" sizes="(max-width:1376px) calc(100vw - 96px), 1280px"><img src="/community/art/community-mobile-unified-480-f245fe9463a3.webp" srcset="/community/art/community-mobile-unified-480-f245fe9463a3.webp 480w, /community/art/community-mobile-unified-960-197666124d82.webp 960w" sizes="calc(100vw - 36px)" width="960" height="480" alt="" loading="lazy" decoding="async" fetchpriority="low"></picture>
    </div>
    <div class="board-tools"><div class="board-filters"><span class="count">${query.get('q')?t("검색 결과"):t("전체 글")}<span>${numberText(data.total)}</span></span><span data-list-categories>${categorySelect(ctx.boards)}</span></div>
    <form class="search" role="search"><input ${interactive?'':'disabled'} name="q" type="search" aria-label="${t("게시글 검색")}" placeholder="${t("제목·본문·글쓴이 검색")}" value="${esc(params.get('q')||'')}" maxlength="40"><button type="submit" ${interactive?'':'disabled'}>${t("검색")}</button></form></div>
    ${data.items.length?`<table class="post-table"><caption class="sr-only">${t("커뮤니티 게시글 목록")}</caption><thead><tr><th class="number-col" scope="col">${t("번호")}</th><th class="title-col" scope="col">${t("제목")}</th><th class="author-col" scope="col">${t("글쓴이")}</th><th class="date-col" scope="col">${t("작성일")}</th><th class="views-col" scope="col">${t("조회")}</th><th class="votes-col" scope="col">${t("추천")}</th></tr></thead><tbody>${data.items.map(row=>`<tr class="${row.is_notice?'notice-row':''}"><td class="number-col">${row.is_notice?`<span class="notice-label">${t("공지")}</span>`:(number=>row.pinned?`<span class="notice-label">${t("고정")}</span>`:numberText(number))(firstNumber-ordinaryIndex++)}</td><td class="title-col"><a href="#post/${row.id}" data-post-id="${row.id}">${row.is_notice?`<span class="notice-label">${t("공지")} </span>`:''}${row.board_name?`<span class="category-label">${esc(categoryName(row.board_name))}</span>`:''}${esc(row.title)}${row.replies?`<span class="comment-count">[${row.replies}]</span>`:''}${row.locked?` <span class="small-text muted">${t("잠김")}</span>`:''}</a><div class="mobile-meta"><span>${esc(row.username)}</span><span>${esc(dateText(row.created_at,{dateOnly:true}))}</span><span class="view-count">${t("조회")} ${numberText(row.view_count||0)}</span><span class="rec">${t("추천")} ${numberText(row.likes||0)}</span></div></td><td class="author-col">${esc(row.username)}</td><td class="date-col">${esc(dateText(row.created_at,{dateOnly:true}))}</td><td class="views-col">${numberText(row.view_count||0)}</td><td class="votes-col">${row.likes||0}</td></tr>`).join('')}</tbody></table>`:
    `<div class="empty"><h2>${params.get('q')?t("검색 결과가 없습니다."):t("아직 게시글이 없습니다.")}</h2><p data-list-empty-hint>${params.get('q')?t("다른 검색어로 다시 찾아보세요."):!ctx.status?'':!canWrite?t("새 글쓰기가 재개되면 이야기를 나눌 수 있습니다."):t("첫 이야기를 남겨 주세요.")}</p>${params.get('q')?`<a class="button" href="#list">${t("전체 글 보기")}</a>`:`<span data-list-write>${write}</span>`}</div>`}
    <div class="board-bottom"><a class="button primary" href="#list">${t("전체글")}</a><span class="muted small-text">${t("{page} / {pages} 페이지",{page:data.page,pages:data.pages})}</span><span data-list-write>${write}</span></div>
    <p data-list-context-error class="small-text" role="status" hidden></p>
    ${data.pages>1?`<nav class="pagination" aria-label="${t("게시글 페이지")}">${data.page>1?`<a href="${esc(pageLink(data.page-1))}" aria-label="${t("이전 페이지")}">${t("이전")}</a>`:''}${pages.map(page=>`<a href="${esc(pageLink(page))}" ${page===data.page?'aria-current="page"':''}>${page}</a>`).join('')}${data.page<data.pages?`<a href="${esc(pageLink(data.page+1))}" aria-label="${t("다음 페이지")}">${t("다음")}</a>`:''}</nav>`:''}`;
}
